  }

  .todo-item .delete-btn:hover {
    color: #e74c3c;
    background: #fdecea;
  }

  .empty-state {
    text-align: center;
    padding: 40px 20px;
    color: #999;
    font-size: 14px;
  }

  .stats {
    margin-top: 12px;
    text-align: center;
    font-size: 13px;
    color: #888;
  }
</style>
</head>
<body>
  <div class="app">
    <h1>Todo List</h1>
    <div class="input-row">
      <input type="text" id="todoInput" placeholder="What needs to be done?" />
      <button id="addBtn">Add</button>
    </div>
    <div class="filters">
      <button data-filter="all" class="active">All</button>
      <button data-filter="active">Active</button>
      <button data-filter="completed">Completed</button>
    </div>
    <ul class="todo-list" id="todoList"></ul>
    <div class="stats" id="stats"></div>
  </div>

<script>
(function() {
  const STORAGE_KEY = 'todo_openrouter-upstage-solar-pro4_01';

  let todos = [];
  let currentFilter = 'all';

  const todoInput = document.getElementById('todoInput');
  const addBtn = document.getElementById('addBtn');
  const todoList = document.getElementById('todoList');
  const statsEl = document.getElementById('stats');
  const filterBtns = document.querySelectorAll('.filters button');

  function loadTodos() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        todos = JSON.parse(stored);
      } else {
        todos = [];
      }
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function addTodo(text) {
    const trimmed = text.trim();
    if (!trimmed) return;
    todos.push({
      id: Date.now() + Math.random(),
      text: trimmed,
      completed: false,
      createdAt: Date.now()
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      saveTodos();
      render();
    }
  }

  function deleteTodo(id) {
    todos = todos.filter(t => t.id !== id);
    saveTodos();
    render();
  }

  function setFilter(filter) {
    currentFilter = filter;
    filterBtns.forEach(btn => {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });
    render();
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') {
      return todos.filter(t => !t.completed);
    } else if (currentFilter === 'completed') {
      return todos.filter(t => t.completed);
    }
    return todos;
  }

  function render() {
    const filtered = getFilteredTodos();
    todoList.innerHTML = '';

    if (filtered.length === 0) {
      const emptyMsg = currentFilter === 'all' ? 'No todos yet. Add one above!' :
                       currentFilter === 'active' ? 'No active todos.' :
                       'No completed todos.';
      const li = document.createElement('li');
      li.className = 'empty-state';
      li.textContent = emptyMsg;
      todoList.appendChild(li);
    } else {
      filtered.forEach(todo => {
        const li = document.createElement('li');
        li.className = 'todo-item';

        const checkbox = document.createElement('div');
        checkbox.className = 'checkbox' + (todo.completed ? ' checked' : '');
        checkbox.setAttribute('role', 'button');
        checkbox.setAttribute('tabindex', '0');
        checkbox.addEventListener('click', () => toggleTodo(todo.id));
        checkbox.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            toggleTodo(todo.id);
          }
        });

        const textSpan = document.createElement('span');
        textSpan.className = 'text' + (todo.completed ? ' completed' : '');
        textSpan.textContent = todo.text;

        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'delete-btn';
        deleteBtn.textContent = '×';
        deleteBtn.setAttribute('aria-label', 'Delete todo');
        deleteBtn.addEventListener('click', () => deleteTodo(todo.id));

        li.appendChild(checkbox);
        li.appendChild(textSpan);
        li.appendChild(deleteBtn);
        todoList.appendChild(li);
      });
    }

    const activeCount = todos.filter(t => !t.completed).length;
    const completedCount = todos.filter(t => t.completed).length;
    if (todos.length > 0) {
      statsEl.textContent = `${activeCount} item${activeCount !== 1 ? 's' : ''} left`;
    } else {
      statsEl.textContent = '';
    }
  }

  addBtn.addEventListener('click', () => {
    addTodo(todoInput.value);
    todoInput.value = '';
    todoInput.focus();
  });

  todoInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      addTodo(todoInput.value);
      todoInput.value = '';
      todoInput.focus();
    }
  });

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => setFilter(btn.dataset.filter));
  });

  loadTodos();
  render();
})();
</script>
</body>
</html>
